Seed.example:
#include <cinux/random.hpp>

using namespace cinux::base::random;

void Example() {
    Generator generator;        // 四个状态字全零，还没播种
    Seed(generator, 0xC0FFEE);  // 一个字搅出四份状态
    // generator.state = {0xCA8216FA9058D0FA, 0xECE45BABCE870479,
    //                    0x87BE93A4A16A73CB, 0x5A71C08957A50D44}
}

SplitMix64.example:
#include <cinux/random.hpp>

using namespace cinux::base::random;

void Example() {
    uint64_t seed = 0;
    const uint64_t mixed = SplitMix64(seed);
    // mixed = 0xE220A8397B1DCDAF · seed 同时推进到 0x9E3779B97F4A7C15
}

Next.example:
#include <cinux/random.hpp>

using namespace cinux::base::random;

void Example() {
    Generator generator;
    Seed(generator, 42);                    // 播种，让状态离开全零
    const uint64_t word = Next(generator);  // 取第一个字，状态同时推进
    // word = 0x15780B2E0C2EC716
}
